import { useDispatch, useSelector } from 'react-redux';

import { RootState } from 'app/appStore';
import { type AdvCampaignRead } from 'entities/Brand';

import {
	setAdvCampaign,
	setIsOpenCreateAutomationDrawer,
	setIsOpenDetailsPopup,
	setIsOpenSaveToAutomationsDrawer,
	setVisitedAdvCampaign,
} from '../model/brandSlice';

export const useBrandSlice = () => {
	const dispatch = useDispatch();

	return {
		...useSelector((s: RootState) => s.brandSlice),
		setAdvCampaign: (offset: AdvCampaignRead) => dispatch(setAdvCampaign(offset)),
		setIsOpenSaveToAutomationsDrawer: (offset: boolean) => dispatch(setIsOpenSaveToAutomationsDrawer(offset)),
		setIsOpenCreateAutomationDrawer: (offset: boolean) => dispatch(setIsOpenCreateAutomationDrawer(offset)),
		setIsOpenDetailsPopup: (offset: boolean) => dispatch(setIsOpenDetailsPopup(offset)),
		setVisitedAdvCampaign: (offset: string) => dispatch(setVisitedAdvCampaign(offset)),
	};
};
